1	import { createHash } from "node:crypto";
2	import type { User } from "@prisma/client";
3	
4	/**
5	 * Prisma on demand. `hashToken`, `extractBearer` and `tokenHasScope` are pure,
6	 * and `tokenHasScope` is an authorization decision — the kind of thing that has
7	 * to be exercised directly by a test rather than reasoned about. A top-level
8	 * `import { db }` made that impossible without pointing Prisma at the production
9	 * DATABASE_URL in /opt/nxeon/.env just to evaluate a string comparison.
10	 */
11	async function prisma() {
12	  return (await import("./db")).db;
13	}
14	
15	/**
16	 * Bearer-token authentication for the public REST API (`/api/v1/*`).
17	 *
18	 * Tokens are formatted `nxe_<prefix>_<random>` and only their sha256 hash is
19	 * stored (never the plaintext). Given an incoming request, resolve the bearer
20	 * token to its owning user, honouring `revoked` and `expiresAt`, and stamp
21	 * `lastUsedAt`.
22	 */
23	
24	export const TOKEN_PREFIX = "nxe";
25	
26	/** Extract the raw bearer token from an `Authorization: Bearer …` header. */
27	export function extractBearer(req: Request): string | null {
28	  const header = req.headers.get("authorization") ?? req.headers.get("Authorization");
29	  if (!header) return null;
30	  const match = /^Bearer\s+(.+)$/i.exec(header.trim());
31	  return match ? match[1].trim() : null;
32	}
33	
34	/** sha256 hex hash of a token — the value stored in `ApiToken.tokenHash`. */
35	export function hashToken(token: string): string {
36	  return createHash("sha256").update(token).digest("hex");
37	}
38	
39	export type ApiAuthResult =
40	  | { ok: true; user: User; tokenId: string; scopes: string[] }
41	  | { ok: false; status: number; error: string };
42	
43	/**
44	 * Authenticate an API request by its bearer token.
45	 * Returns the resolved user + token scopes, or a structured error with an
46	 * appropriate HTTP status for the route to return.
47	 */
48	export async function authenticateApiToken(req: Request): Promise<ApiAuthResult> {
49	  const raw = extractBearer(req);
50	  if (!raw) return { ok: false, status: 401, error: "Missing bearer token" };
51	  if (!raw.startsWith(`${TOKEN_PREFIX}_`)) {
52	    return { ok: false, status: 401, error: "Invalid token format" };
53	  }
54	
55	  const db = await prisma();
56	  const tokenHash = hashToken(raw);
57	  const token = await db.apiToken.findUnique({
58	    where: { tokenHash },
59	    include: { user: true },
60	  });
61	
62	  if (!token) return { ok: false, status: 401, error: "Invalid token" };
63	  if (token.revoked) return { ok: false, status: 401, error: "Token has been revoked" };
64	  if (token.expiresAt && token.expiresAt < new Date()) {
65	    return { ok: false, status: 401, error: "Token has expired" };
66	  }
67	  if (!token.user || token.user.suspended) {
68	    return { ok: false, status: 403, error: "Account unavailable" };
69	  }
70	
71	  // Best-effort lastUsedAt stamp — never block the request on this write.
72	  db.apiToken
73	    .update({ where: { id: token.id }, data: { lastUsedAt: new Date() } })
74	    .catch(() => {});
75	
76	  return { ok: true, user: token.user, tokenId: token.id, scopes: token.scopes };
77	}
78	
79	/**
80	 * Whether an authenticated token carries a given scope.
81	 *
82	 * A scope is `resource:action` (`servers:read`). A token satisfies a request if
83	 * it carries:
84	 *   - the exact requested scope, or
85	 *   - the global wildcard `*`, or
86	 *   - the resource wildcard `servers:*`, or
87	 *   - the generic `read` scope, which satisfies any `*:read` request.
88	 *
89	 * ── EMPTY SCOPES ARE READ-ONLY, NOT FULL ACCESS ──────────────────────────────
90	 *
91	 * A token with no scopes recorded predates scoping. It used to return true for
92	 * ANY request — `if (scopes.length === 0) return true` — which is not
93	 * "backward compatible", it is "unscoped means unlimited". It survived review
94	 * only because the public API happens to be read-only today: `GET /api/v1/servers`
95	 * is the single token-authenticated route in the codebase. The first mutating
96	 * endpoint to land would have silently granted every legacy token the right to
97	 * call it, and nobody adding that endpoint would have had any reason to look here.
98	 *
99	 * A customer who created a token before scopes existed consented to reading their
100	 * account, because reading is all the API could do. They did not consent to a
101	 * future `servers:delete`. So an empty scope list now means exactly that: reads,
102	 * and nothing else. Fail closed, and let the failure be a 403 on a new endpoint
103	 * rather than a deletion nobody authorised.
104	 */
105	export function tokenHasScope(auth: ApiAuthResult, scope: string): boolean {
106	  if (!auth.ok) return false;
107	  if (!scope || typeof scope !== "string") return false;
108	  const scopes = auth.scopes ?? [];
109	  const [resource, action] = scope.split(":");
110	
111	  if (scopes.length === 0) {
112	    // Legacy, pre-scoping token: reads only. `servers:read` yes, anything that
113	    // changes state no.
114	    return action === "read";
115	  }
116	  if (scopes.includes("*") || scopes.includes(scope)) return true;
117	  if (resource && scopes.includes(`${resource}:*`)) return true;
118	  if (action === "read" && scopes.includes("read")) return true;
119	  return false;
120	}
121	
122	/**
123	 * Authenticate AND authorize in one call — the form every `/api/v1` route should
124	 * use.
125	 *
126	 * `tokenHasScope` on its own is advisory: nothing makes a route call it, and a
127	 * route that forgets is authenticated-but-unauthorized, which looks completely
128	 * normal in review. That is the second half of the same footgun, and it cannot be
129	 * fixed by being careful. It is fixed by there being a single entry point that
130	 * cannot answer "who is this" without also being told "to do what", plus the
131	 * tripwire in test/api-http-surface.test.ts asserting that no route under
132	 * app/api/v1 authenticates a token without checking a scope.
133	 *
134	 * Returns the same discriminated union as `authenticateApiToken`, so a route
135	 * handles one error shape:
136	 *
137	 *     const auth = await authorizeApiRequest(req, "servers:read");
138	 *     if (!auth.ok) return NextResponse.json({ error: auth.error }, { status: auth.status });
139	 */
140	export async function authorizeApiRequest(
141	  req: Request,
142	  scope: string,
143	): Promise<ApiAuthResult> {
144	  const auth = await authenticateApiToken(req);
145	  if (!auth.ok) return auth;
146	  if (!tokenHasScope(auth, scope)) {
147	    return { ok: false, status: 403, error: `Token is missing the required scope: ${scope}` };
148	  }
149	  return auth;
150	}
