1	import { SignJWT, jwtVerify, type JWTPayload } from "jose";
2	import { cookies } from "next/headers";
3	import { cache } from "react";
4	import { db } from "./db";
5	import { getSettingInt } from "./settings";
6	import type { User } from "@prisma/client";
7	
8	const secret = new TextEncoder().encode(process.env.AUTH_SECRET!);
9	const COOKIE = process.env.NXEON_COOKIE_NAME ?? "nxeon_session";
10	
11	export async function createSession(userId: string) {
12	  // Session lifetime is admin-configurable (`session_length_days`, default 30).
13	  // Both the JWT expiry and the cookie maxAge use it so they stay in sync.
14	  const days = Math.max(1, await getSettingInt("session_length_days", 30));
15	  // Embed the account's current sessionVersion so a bump (password change/reset)
16	  // invalidates every previously-issued token. Missing => treated as 0.
17	  const acct = await db.user.findUnique({ where: { id: userId }, select: { sessionVersion: true } });
18	  // `typ` distinguishes this from the impersonation token below. Both are signed
19	  // with the SAME secret, so without it the two are interchangeable strings —
20	  // see the note on `assertSessionToken`.
21	  const token = await new SignJWT({ sub: userId, sv: acct?.sessionVersion ?? 0, typ: "session" })
22	    .setProtectedHeader({ alg: "HS256" })
23	    .setIssuedAt()
24	    .setExpirationTime(`${days}d`)
25	    .sign(secret);
26	  const jar = await cookies();
27	  const secure = process.env.NODE_ENV === "production" && process.env.COOKIE_SECURE === "1";
28	  jar.set(COOKIE, token, {
29	    httpOnly: true,
30	    sameSite: "lax",
31	    secure,
32	    maxAge: 60 * 60 * 24 * days,
33	    path: "/",
34	  });
35	  // Non-sensitive, JS-readable flag so the (static) marketing header can show
36	  // "Dashboard" instead of "Login/Get started" for a signed-in visitor. Carries
37	  // no identity — just presence. Always cleared alongside the session cookie.
38	  jar.set("nxeon_authed", "1", {
39	    httpOnly: false,
40	    sameSite: "lax",
41	    secure,
42	    maxAge: 60 * 60 * 24 * days,
43	    path: "/",
44	  });
45	}
46	
47	export async function destroySession() {
48	  const jar = await cookies();
49	  jar.delete(COOKIE);
50	  jar.delete("nxeon_authed");
51	}
52	
53	/**
54	 * Is this payload allowed to act as a SESSION, as opposed to an impersonation
55	 * grant?
56	 *
57	 * Both cookies are HS256 over the same `AUTH_SECRET`, so as far as `jwtVerify`
58	 * is concerned an impersonation token is a perfectly valid session token — the
59	 * only difference was which claims happened to be present, and nothing checked.
60	 * Moving the value of `nxeon_session_imp` into `nxeon_session` therefore
61	 * produced a REAL session as the impersonated customer: not flagged as
62	 * impersonation, so `impersonating()` returns null, the banner does not render,
63	 * and `audit()` in lib/actions.ts stops appending `actingAdmin=…` — every
64	 * subsequent action is recorded as the customer's own. For a platform holding
65	 * customer servers and saved cards, "an admin can act as a customer with no
66	 * trace" is the accountability failure that matters even though the admin was
67	 * already privileged.
68	 *
69	 * An impersonation grant is also the weaker credential by design (2h, no
70	 * `sessionVersion`), so it must not be promotable into the stronger one: it
71	 * carries no `sv`, which `realUser` reads as 0, and 0 is the DEFAULT
72	 * sessionVersion — so for any account that has never changed its password the
73	 * promotion also survives every existing revocation check.
74	 *
75	 * Old session tokens minted before `typ` existed carry neither claim and stay
76	 * valid, so nobody is signed out by this.
77	 */
78	function assertSessionToken(payload: JWTPayload): boolean {
79	  if (payload.adminId !== undefined) return false;
80	  return payload.typ === undefined || payload.typ === "session";
81	}
82	
83	/**
84	 * Lightweight "is there a valid session?" check — verifies the session JWT
85	 * (signature + expiry) WITHOUT a DB round-trip. Used by /api/auth/status so the
86	 * (static) marketing header can authoritatively show "Back to portal" even when
87	 * the non-httpOnly `nxeon_authed` flag cookie is missing or stale.
88	 *
89	 * KNOWN AND ACCEPTED LIMIT: with no DB round-trip this cannot see a
90	 * `sessionVersion` bump or a suspension, so for a revoked session it can still
91	 * answer `true`. That is deliberate — this endpoint is hit by the marketing
92	 * header on every page view, and it decides nothing but which of two links to
93	 * draw. Every route that actually grants access goes through `realUser`, which
94	 * does check both. Do not reach for this function to authorise anything.
95	 */
96	export async function isSignedIn(): Promise<boolean> {
97	  const jar = await cookies();
98	  const token = jar.get(COOKIE)?.value;
99	  if (!token) return false;
100	  try {
101	    const { payload } = await jwtVerify(token, secret);
102	    return assertSessionToken(payload);
103	  } catch {
104	    return false;
105	  }
106	}
107	
108	const IMP_COOKIE = `${process.env.NXEON_COOKIE_NAME ?? "nxeon_session"}_imp`;
109	
110	/** The real signed-in account, ignoring any impersonation. */
111	export const realUser = cache(async (): Promise<User | null> => {
112	  const jar = await cookies();
113	  const token = jar.get(COOKIE)?.value;
114	  if (!token) return null;
115	  try {
116	    const { payload } = await jwtVerify(token, secret);
117	    if (!payload.sub) return null;
118	    // An impersonation grant is not a session (see assertSessionToken).
119	    if (!assertSessionToken(payload)) return null;
120	    const user = await db.user.findUnique({ where: { id: payload.sub } });
121	    if (!user || user.suspended) return null;
122	    // Session revocation: a token is only valid while its embedded version matches
123	    // the account's current sessionVersion. Older tokens without `sv` count as 0,
124	    // so accounts that never bumped stay logged in (backward-compatible).
125	    const tokenVer = typeof payload.sv === "number" ? payload.sv : 0;
126	    if (tokenVer !== (user.sessionVersion ?? 0)) return null;
127	    return user;
128	  } catch {
129	    return null;
130	  }
131	});
132	
133	/** Effective user: the impersonated customer if an admin is impersonating, else the real user. */
134	export const currentUser = cache(async (): Promise<User | null> => {
135	  const real = await realUser();
136	  if (!real) return null;
137	  if (real.role === "ADMIN") {
138	    const jar = await cookies();
139	    const imp = jar.get(IMP_COOKIE)?.value;
140	    if (imp) {
141	      try {
142	        const { payload } = await jwtVerify(imp, secret);
143	        if (payload.typ === "imp" && payload.adminId === real.id && typeof payload.sub === "string") {
144	          const target = await db.user.findUnique({ where: { id: payload.sub } });
145	          // The token outlives the checks `impersonateUser` made when it minted
146	          // it (2h), so they are re-made here against the CURRENT row rather
147	          // than trusted from the past:
148	          //
149	          //  - suspended: `realUser` refuses to hand out a session for a
150	          //    suspended account, and impersonation must not be a side door that
151	          //    resurrects one. Reviewing a suspended abuser's account is a
152	          //    read-only job; it must not come with the ability to act as them.
153	          //  - ADMIN: refused at mint time, but a customer promoted DURING an
154	          //    open impersonation would otherwise turn the impersonator's
155	          //    `currentUser()` into an ADMIN — and `requireAdmin` is built on
156	          //    `currentUser`, so admin actions would run attributed to the
157	          //    promoted account instead of the person taking them. The rule that
158	          //    admins refuse to act while impersonating depends on this.
159	          //
160	          // Falling through to the real admin is the safe failure: they are
161	          // simply themselves again, which is visible on screen.
162	          if (target && !target.suspended && target.role !== "ADMIN") return target;
163	        }
164	      } catch {
165	        /* expired/invalid impersonation — fall through to real user */
166	      }
167	    }
168	  }
169	  return real;
170	});
171	
172	/** Non-null when the current request is an admin impersonating a customer. */
173	export const impersonating = cache(async (): Promise<{ admin: User; target: User } | null> => {
174	  const real = await realUser();
175	  if (!real || real.role !== "ADMIN") return null;
176	  const target = await currentUser();
177	  if (!target || target.id === real.id) return null;
178	  return { admin: real, target };
179	});
180	
181	export async function setImpersonation(targetUserId: string) {
182	  const real = await realUser();
183	  if (!real || real.role !== "ADMIN") throw new Error("FORBIDDEN");
184	  // `typ: "imp"` marks this as a grant, never a session (see assertSessionToken).
185	  const token = await new SignJWT({ sub: targetUserId, adminId: real.id, typ: "imp" })
186	    .setProtectedHeader({ alg: "HS256" })
187	    .setIssuedAt()
188	    .setExpirationTime("2h")
189	    .sign(secret);
190	  const jar = await cookies();
191	  jar.set(IMP_COOKIE, token, {
192	    httpOnly: true,
193	    sameSite: "lax",
194	    secure: process.env.NODE_ENV === "production",
195	    path: "/",
196	    maxAge: 7200,
197	  });
198	}
199	
200	export async function clearImpersonation() {
201	  const jar = await cookies();
202	  jar.delete(IMP_COOKIE);
203	}
204	
205	/**
206	 * Guard for wallet-debit / paid actions: refuse to run while an admin is
207	 * impersonating a customer. Keeps money movements attributable to the account
208	 * holder and prevents an admin from spending a customer's balance on their behalf.
209	 * Throws a friendly, user-facing error. Call at the top of every spend path.
210	 */
211	export async function assertNotImpersonating(): Promise<void> {
212	  const imp = await impersonating();
213	  if (imp) {
214	    throw new Error(
215	      "This action is disabled while impersonating a customer. Stop impersonating to continue.",
216	    );
217	  }
218	}
219	
220	export async function requireUser(): Promise<User> {
221	  const user = await currentUser();
222	  if (!user) throw new Error("UNAUTHORIZED");
223	  return user;
224	}
225	
226	export async function requireAdmin(): Promise<User> {
227	  const user = await requireUser();
228	  if (user.role !== "ADMIN") throw new Error("FORBIDDEN");
229	  return user;
230	}
231	
232	/**
233	 * Require any staff role (SUPPORT / BILLING / ADMIN). Uses the real signed-in
234	 * account, ignoring impersonation. Throws FORBIDDEN for customers. Fine-grained
235	 * per-area gating lives in lib/rbac.ts (`requireArea`).
236	 */
237	export async function requireStaff(): Promise<User> {
238	  const user = await realUser();
239	  if (!user) throw new Error("UNAUTHORIZED");
240	  if (user.role !== "SUPPORT" && user.role !== "BILLING" && user.role !== "ADMIN") {
241	    throw new Error("FORBIDDEN");
242	  }
243	  return user;
244	}
245

1	"use server";
2	
3	import { revalidatePath } from "next/cache";
4	import { redirect } from "next/navigation";
5	import { headers } from "next/headers";
6	import bcrypt from "bcryptjs";
7	import { z } from "zod";
8	import { db } from "./db";
9	import {
10	  requireUser,
11	  requireAdmin,
12	  setImpersonation,
13	  clearImpersonation,
14	  createSession,
15	} from "./auth";
16	import { checkRateLimit, clientIp } from "./rate-limit";
17	import { mayDeliverTo } from "./prefs";
18	import { normalizeEmail } from "./email-normalize";
19	
20	// ---------- Profile ----------
21	
22	export async function updateProfile(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
23	  const user = await requireUser();
24	  const name = String(formData.get("name") ?? "").trim();
25	  if (name.length < 1 || name.length > 100) return { error: "Enter a valid name." };
26	  await db.user.update({ where: { id: user.id }, data: { name } });
27	  revalidatePath("/dashboard/settings");
28	  return { ok: true };
29	}
30	
31	export async function changePassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
32	  const user = await requireUser();
33	  const current = String(formData.get("current") ?? "");
34	  const next = String(formData.get("next") ?? "");
35	  if (next.length < 8) return { error: "New password must be at least 8 characters." };
36	  if (!(await bcrypt.compare(current, user.passwordHash))) return { error: "Current password is incorrect." };
37	  // Bump sessionVersion to evict every other outstanding session, then re-issue a
38	  // fresh token for THIS session so the user who changed the password stays in.
39	  await db.user.update({
40	    where: { id: user.id },
41	    data: { passwordHash: await bcrypt.hash(next, 12), sessionVersion: { increment: 1 } },
42	  });
43	  await createSession(user.id);
44	  return { ok: true };
45	}
46	
47	/**
48	 * Evict every OTHER logged-in session for this account (a stolen/borrowed device,
49	 * a shared computer left signed in) while keeping the caller signed in. Same
50	 * mechanism as a password change: bump sessionVersion so every existing token
51	 * fails the version check, then re-issue a fresh token for THIS session.
52	 */
53	export async function signOutOtherSessions(): Promise<{ ok?: boolean; error?: string }> {
54	  const user = await requireUser();
55	  await db.user.update({
56	    where: { id: user.id },
57	    data: { sessionVersion: { increment: 1 } },
58	  });
59	  await createSession(user.id);
60	  return { ok: true };
61	}
62	
63	// ---------- SSH keys ----------
64	
65	export async function addSshKey(prev: any, formData: FormData): Promise<{ error?: string }> {
66	  const user = await requireUser();
67	  const parsed = z
68	    .object({
69	      name: z.string().min(1).max(60),
70	      publicKey: z.string().min(20).max(4000).regex(/^(ssh-(rsa|ed25519)|ecdsa-sha2-\S+)\s+\S+/, "Not a valid OpenSSH public key"),
71	    })
72	    .safeParse({ name: formData.get("name"), publicKey: String(formData.get("publicKey") ?? "").trim() });
73	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Invalid key." };
74	  await db.sshKey.create({ data: { userId: user.id, ...parsed.data } });
75	  revalidatePath("/dashboard/settings");
76	  return {};
77	}
78	
79	export async function deleteSshKey(keyId: string) {
80	  const user = await requireUser();
81	  await db.sshKey.deleteMany({ where: { id: keyId, userId: user.id } });
82	  revalidatePath("/dashboard/settings");
83	}
84	
85	// ---------- Projects ----------
86	
87	export async function createProject(prev: any, formData: FormData): Promise<{ error?: string }> {
88	  const user = await requireUser();
89	  const name = String(formData.get("name") ?? "").trim();
90	  const color = String(formData.get("color") ?? "#6f47f5");
91	  if (name.length < 1 || name.length > 50) return { error: "Project name: 1–50 characters." };
92	  await db.project.create({ data: { userId: user.id, name, color } });
93	  revalidatePath("/dashboard/projects");
94	  return {};
95	}
96	
97	export async function deleteProject(projectId: string) {
98	  const user = await requireUser();
99	  await db.project.deleteMany({ where: { id: projectId, userId: user.id } });
100	  revalidatePath("/dashboard/projects");
101	}
102	
103	export async function assignServerProject(serverId: string, projectId: string | null) {
104	  const user = await requireUser();
105	  const server = await db.server.findUnique({ where: { id: serverId } });
106	  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) throw new Error("Forbidden");
107	  if (projectId) {
108	    const project = await db.project.findFirst({ where: { id: projectId, userId: server.userId } });
109	    if (!project) throw new Error("Project not found");
110	  }
111	  await db.server.update({ where: { id: serverId }, data: { projectId } });
112	  revalidatePath(`/dashboard/servers/${serverId}`);
113	}
114	
115	// ---------- Notifications ----------
116	
117	export async function markNotificationsRead() {
118	  const user = await requireUser();
119	  await db.notification.updateMany({
120	    where: { userId: user.id, readAt: null },
121	    data: { readAt: new Date() },
122	  });
123	  revalidatePath("/dashboard");
124	}
125	
126	// ---------- Password reset (email-based) ----------
127	
128	export async function requestPasswordReset(prev: any, formData: FormData): Promise<{ sent?: boolean }> {
129	  // This lookup was ALREADY lowercasing while register/login stored the address
130	  // verbatim, which is precisely why a `Alice@Example.com` signup could never be
131	  // reset. Both sides now share one definition rather than two that agreed by
132	  // luck — see lib/email-normalize.ts.
133	  const email = normalizeEmail(formData.get("email"));
134	  // Throttle per email+IP (same helper login uses) to curb reset-email flooding
135	  // and enumeration probing. On limit, still report success below (no leak).
136	  //
137	  // `clientIp` rather than the first `x-forwarded-for` entry, which is a field
138	  // the CALLER fills in (nginx appends the real address, it does not replace the
139	  // header). Keying on it let one script vary the fake value per request and get
140	  // a fresh 5-attempt allowance every time, which mattered twice over here: it
141	  // uncapped the reset-mail flood AND it removed the cap on the timing probe
142	  // below.
143	  const ip = clientIp(await headers());
144	  const rl = checkRateLimit(`pwreset:${email}:${ip}`, { max: 5, windowMs: 15 * 60 * 1000 });
145	  if (!rl.ok) return { sent: true };
146	  // Always report success (don't leak which emails exist)
147	  const user = await db.user.findUnique({ where: { email } });
148	  if (user) {
149	    const { randomBytes, createHash } = await import("node:crypto");
150	    const token = randomBytes(32).toString("base64url");
151	    const tokenHash = createHash("sha256").update(token).digest("hex");
152	    await db.passwordResetToken.create({
153	      data: { userId: user.id, tokenHash, expiresAt: new Date(Date.now() + 3600_000) },
154	    });
155	    const { sendMail, emails } = await import("./mailer");
156	    const link = `${process.env.APP_URL ?? "https://nxeon.cloud"}/reset-password?token=${token}`;
157	    const tpl = emails.passwordReset(link);
158	    // THE SEND IS DELIBERATELY NOT AWAITED, and that is a security property, not
159	    // an optimisation.
160	    //
161	    // "If an account exists for that email, a reset link is on its way" is the
162	    // right answer and is returned either way — but only ONE of the two branches
163	    // used to open an SMTP conversation before answering. A known address took
164	    // as long as the mail server did; an unknown one returned after a single
165	    // indexed SELECT. The wording revealed nothing and the clock revealed
166	    // everything, one sample per address, which is a working account-enumeration
167	    // oracle against a hosting provider's whole customer list. Detaching the send
168	    // leaves the two branches differing by one INSERT.
169	    //
170	    // Nothing is lost by not waiting: the result was already discarded, and the
171	    // customer was never told whether it worked. Failures are logged, and the
172	    // rejection is swallowed so a dead mail server can never take the process
173	    // down through an unhandled rejection.
174	    //
175	    // `mayDeliverTo` consults the notification policy, which classifies
176	    // `password_reset` as CRITICAL and returns true without even loading the
177	    // preferences. The call is here so the POLICY decides, not this call site: a
178	    // reset link is the only route back into a locked-out account, so honouring
179	    // an "Account email: off" checkbox here would lock the customer out of their
180	    // own account permanently.
181	    void (async () => {
182	      if (await mayDeliverTo(user.id, "password_reset", "email")) {
183	        await sendMail({ to: email, subject: tpl.subject, html: tpl.html });
184	      }
185	    })().catch((e) => {
186	      console.error("[password-reset] send failed:", e);
187	    });
188	    await db.auditLog.create({ data: { userId: user.id, action: "user.password_reset_request" } });
189	  }
190	  return { sent: true };
191	}
192	
193	export async function resetPassword(prev: any, formData: FormData): Promise<{ error?: string; ok?: boolean }> {
194	  const token = String(formData.get("token") ?? "");
195	  const password = String(formData.get("password") ?? "");
196	  if (password.length < 8) return { error: "Password must be at least 8 characters." };
197	  const { createHash } = await import("node:crypto");
198	  const tokenHash = createHash("sha256").update(token).digest("hex");
199	  const row = await db.passwordResetToken.findUnique({ where: { tokenHash } });
200	  if (!row || row.usedAt || row.expiresAt < new Date()) {
201	    return { error: "This reset link is invalid or has expired. Request a new one." };
202	  }
203	  await db.$transaction([
204	    // Bump sessionVersion so any sessions predating the reset are evicted.
205	    db.user.update({
206	      where: { id: row.userId },
207	      data: { passwordHash: await bcrypt.hash(password, 12), sessionVersion: { increment: 1 } },
208	    }),
209	    db.passwordResetToken.update({ where: { id: row.id }, data: { usedAt: new Date() } }),
210	    db.auditLog.create({ data: { userId: row.userId, action: "user.password_reset_complete" } }),
211	  ]);
212	  return { ok: true };
213	}
