1	import { createHmac, randomBytes, timingSafeEqual } from "node:crypto";
2	
3	/**
4	 * Dependency-free TOTP (RFC 6238) using only node:crypto.
5	 * - HMAC-SHA1 over a 30-second time counter
6	 * - 6-digit codes, verified with a ±1 step window
7	 * This is a plain module (no "use server"): it exports pure helpers.
8	 */
9	
10	const BASE32_ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ234567";
11	const DIGITS = 6;
12	const STEP_SECONDS = 30;
13	
14	/** Encode raw bytes to an (unpadded) RFC 4648 base32 string. */
15	function base32Encode(buf: Buffer): string {
16	  let bits = 0;
17	  let value = 0;
18	  let out = "";
19	  for (const byte of buf) {
20	    value = (value << 8) | byte;
21	    bits += 8;
22	    while (bits >= 5) {
23	      out += BASE32_ALPHABET[(value >>> (bits - 5)) & 31];
24	      bits -= 5;
25	    }
26	  }
27	  if (bits > 0) {
28	    out += BASE32_ALPHABET[(value << (5 - bits)) & 31];
29	  }
30	  return out;
31	}
32	
33	/** Decode a base32 string (case-insensitive, ignores spaces/padding) to bytes. */
34	export function base32Decode(input: string): Buffer {
35	  const clean = input.toUpperCase().replace(/[\s=]/g, "");
36	  let bits = 0;
37	  let value = 0;
38	  const bytes: number[] = [];
39	  for (const char of clean) {
40	    const idx = BASE32_ALPHABET.indexOf(char);
41	    if (idx === -1) continue; // skip invalid chars defensively
42	    value = (value << 5) | idx;
43	    bits += 5;
44	    if (bits >= 8) {
45	      bytes.push((value >>> (bits - 8)) & 0xff);
46	      bits -= 8;
47	    }
48	  }
49	  return Buffer.from(bytes);
50	}
51	
52	/** Generate a new base32 TOTP secret (default 20 bytes = 160 bits). */
53	export function generateSecret(bytes = 20): string {
54	  return base32Encode(randomBytes(bytes));
55	}
56	
57	/** Compute the HMAC-SHA1 dynamic-truncation code for a specific counter. */
58	function hotp(secret: string, counter: number): string {
59	  const key = base32Decode(secret);
60	  const buf = Buffer.alloc(8);
61	  // 64-bit big-endian counter (JS-safe: high 32 bits then low 32 bits)
62	  buf.writeUInt32BE(Math.floor(counter / 0x100000000), 0);
63	  buf.writeUInt32BE(counter >>> 0, 4);
64	  const hmac = createHmac("sha1", key).update(buf).digest();
65	  const offset = hmac[hmac.length - 1] & 0x0f;
66	  const bin =
67	    ((hmac[offset] & 0x7f) << 24) |
68	    ((hmac[offset + 1] & 0xff) << 16) |
69	    ((hmac[offset + 2] & 0xff) << 8) |
70	    (hmac[offset + 3] & 0xff);
71	  return (bin % 10 ** DIGITS).toString().padStart(DIGITS, "0");
72	}
73	
74	/** Current TOTP code (for the given time, default now). */
75	export function generateTOTP(secret: string, atMs: number = Date.now()): string {
76	  return hotp(secret, Math.floor(atMs / 1000 / STEP_SECONDS));
77	}
78	
79	/**
80	 * Which 30-second step a submitted code belongs to, or null if it belongs to
81	 * none within the ±1 window. Constant-time comparison per step.
82	 *
83	 * `verifyTOTP` is the boolean form of this and is what most callers want. The
84	 * counter itself is needed by exactly one caller — the login path — because RFC
85	 * 6238 §5.2 requires that a code be accepted ONCE, and "once" can only be
86	 * enforced against a specific step. A bare boolean cannot express which of the
87	 * three candidate codes matched, so a replayed code is indistinguishable from a
88	 * fresh one. See lib/totp-verify.ts.
89	 *
90	 * The whole window is always walked, even after a match, so the time this takes
91	 * does not reveal WHICH step matched (and therefore does not reveal the
92	 * verifier's clock offset).
93	 */
94	export function matchTOTPCounter(
95	  secret: string,
96	  code: string,
97	  atMs: number = Date.now(),
98	): number | null {
99	  const cleaned = (code ?? "").replace(/\s/g, "");
100	  if (!/^\d{6}$/.test(cleaned)) return null;
101	  const counter = Math.floor(atMs / 1000 / STEP_SECONDS);
102	  let matched: number | null = null;
103	  for (let w = -1; w <= 1; w++) {
104	    const expected = hotp(secret, counter + w);
105	    const a = Buffer.from(expected);
106	    const b = Buffer.from(cleaned);
107	    if (a.length === b.length && timingSafeEqual(a, b) && matched === null) {
108	      matched = counter + w;
109	    }
110	  }
111	  return matched;
112	}
113	
114	/**
115	 * Verify a submitted code against the secret with a ±1 step window
116	 * (tolerates minor clock drift). Constant-time comparison per step.
117	 */
118	export function verifyTOTP(secret: string, code: string, atMs: number = Date.now()): boolean {
119	  return matchTOTPCounter(secret, code, atMs) !== null;
120	}
121	
122	/** Build an otpauth:// URI that authenticator apps can import (also render as QR). */
123	export function otpauthURL(secret: string, label: string, issuer = "Nxeon"): string {
124	  const enc = encodeURIComponent;
125	  const account = `${enc(issuer)}:${enc(label)}`;
126	  const params = new URLSearchParams({
127	    secret,
128	    issuer,
129	    algorithm: "SHA1",
130	    digits: String(DIGITS),
131	    period: String(STEP_SECONDS),
132	  });
133	  return `otpauth://totp/${account}?${params.toString()}`;
134	}
