148	const credsSchema = z.object({
149	  email: z.string().max(200).email("Enter a valid email address"),
150	  password: z.string().min(8).max(200),
151	});
152	
153	export async function register(prev: any, formData: FormData): Promise<{ error?: string }> {
154	  const parsed = credsSchema
155	    .extend({
156	      name: z.string().min(1, "Enter your name").max(100, "Name is too long"),
157	      password: z
158	        .string()
159	        .min(8, "Password must be at least 8 characters")
160	        .max(200, "Password is too long")
161	        .regex(/[a-zA-Z]/, "Password must include a letter")
162	        .regex(/[0-9]/, "Password must include a number"),
163	    })
164	    .safeParse({
165	    // Canonicalise BEFORE validating, so `  Alice@Example.com ` is stored in the
166	    // one form every lookup will use. See lib/email-normalize.ts.
167	    email: normalizeEmail(formData.get("email")),
168	    password: formData.get("password"),
169	    name: formData.get("name"),
170	  });
171	  // Say what is actually wrong. This used to collapse four precise, already
172	  // written messages into "Enter a valid email, name, and password (min 8
173	  // chars)." — so a customer whose only problem was a missing digit was told
174	  // about a length rule their 8-character password already satisfied, and had
175	  // no way to work out what the form wanted. The deploy path (`payAndDeploy`
176	  // below, via lib/order.ts) has surfaced the real issue since it was written;
177	  // this is the same one line.
178	  if (!parsed.success) return { error: parsed.error.issues[0]?.message ?? "Check the form and try again." };
179	  const { email, password, name } = parsed.data;
180	
181	  // Throttle signups per email+IP (reuses the login rate-limit helper) to curb
182	  // automated account creation and welcome-credit farming.
183	  const regIp = clientIp(await headers());
184	  const regRl = checkRateLimit(`register:${email}:${regIp}`, { max: 5, windowMs: 15 * 60 * 1000 });
185	  if (!regRl.ok) return { error: `Too many attempts. Try again in ${regRl.retryAfterSec}s.` };
186	
187	  const existing = await db.user.findUnique({ where: { email } });
188	  if (existing) return { error: "An account with that email already exists." };
189	
190	  // Capture a referral from the `ref` cookie (set by the register page) if the
191	  // code maps to a real user. Self-referral is impossible here (new account).
192	  const jar = await cookies();
193	  const refCode = jar.get(REF_COOKIE)?.value?.trim().toUpperCase();
194	  let referredById: string | null = null;
195	  if (refCode) {
196	    const referrer = await db.user.findUnique({ where: { referralCode: refCode } });
197	    if (referrer) referredById = referrer.id;
198	  }
199	
200	  const referralCode = await uniqueReferralCode();
201	  const user = await db.user.create({
202	    data: {
203	      email,
204	      name,
205	      passwordHash: await bcrypt.hash(password, 12),
206	      referralCode,
207	      referredById,
208	    },
209	  });
210	  await audit(user.id, "user.register", referredById ? `ref=${refCode}` : undefined);
211	  await createSession(user.id);
212	  // Grant signup free credit (no-op unless the configured amount is > 0).
213	  //
214	  // Still non-fatal — a failure here must not cost the customer the account they
215	  // just created — but no longer SILENT. `signup_free_credit_cents` is an
216	  // admin-editable field that the settings panel reports "Saved." for, and an
217	  // empty `catch {}` here is exactly how this codebase has repeatedly ended up
218	  // with a control that reports success and does nothing. If the grant fails,
219	  // that fact is now in the logs and there is a wallet row to reconcile against.
220	  try {
221	    await grantSignupCredit(user.id);
222	  } catch (e) {
223	    console.error("[register] signup credit grant failed for", user.id, e);
224	  }
225	  jar.delete(REF_COOKIE);
226	  try {
227	    const { sendMail, emails } = await import("./mailer");
228	    const tpl = emails.welcome(name);
229	    await sendMail({ to: email, subject: tpl.subject, html: tpl.html, userId: user.id, kind: "welcome" });
230	  } catch { /* email is best-effort */ }
231	  // Send the verification link. Best-effort like the welcome mail and it does
232	  // NOT block the redirect: signing up and looking around stay open, only
233	  // buying and provisioning wait on the click (lib/email-verification.ts). If
234	  // this send fails the account is still usable and still resendable from the
235	  // portal banner — the customer is never stranded on a screen we control.
236	  try {
237	    const { sendVerificationEmail } = await import("./email-verification");
238	    await sendVerificationEmail(user);
239	  } catch (e) {
240	    console.error("[register] verification email failed:", e);
241	  }
242	  redirect("/dashboard");
243	}
