339	/**
340	 * Enforce the admin-configured per-user server cap (`max_servers_per_user`,
341	 * default 10; 0 = unlimited). Counts every server the user owns that isn't being
342	 * torn down (DELETING). Returns an error message when the cap is reached, else null.
343	 */
344	async function serverLimitError(userId: string): Promise<string | null> {
345	  const cap = await getSettingInt("max_servers_per_user", 10);
346	  if (cap <= 0) return null; // 0 (or negative) = unlimited
347	  const owned = await db.server.count({ where: { userId, status: { notIn: ["DELETING"] } } });
348	  if (owned >= cap) {
349	    return `You've reached your limit of ${cap} server${cap === 1 ? "" : "s"}. Delete one or contact support to raise the cap.`;
350	  }
351	  return null;
352	}
