422	    if (quote.couponDiscountCents > 0) return { ok: true, label: quote.couponLabel, discountCents: quote.couponDiscountCents };
423	    return { ok: false, error: "That code doesn’t apply to this order." };
424	  } catch (e) {
425	    if (e instanceof OrderError) return { ok: false, error: e.message };
