971	export async function adminExtendServer(prev: any, formData: FormData): Promise<{ error?: string }> {
972	  const admin = await requireAdmin();
973	  const serverId = String(formData.get("serverId") ?? "");
974	  const days = Number(formData.get("days"));
975	  if (!serverId || !Number.isFinite(days) || days === 0 || Math.abs(days) > 365) {
976	    return { error: "Days must be between -365 and 365." };
977	  }
978	  const server = await db.server.findUnique({ where: { id: serverId } });
979	  if (!server) return { error: "Server not found." };
980	  const base = server.expiresAt ? server.expiresAt.getTime() : Date.now();
981	
982	  // ─── EXPIRESAT INTEGRITY ────────────────────────────────────────────────────
983	  // The whole proration model rests on "every month between now and `expiresAt` is
984	  // a month the customer has actually bought" (see lib/proration.ts
985	  // remainingMonths). This action moves `expiresAt` by up to a year per call, with
986	  // no call limit and no payment — so before the persisted rate existed, an admin
987	  // goodwill gift of 12 months was directly convertible to cash: downgrade the
988	  // gifted server and the prorated credit paid out real wallet money for months
989	  // nobody had ever been charged for. Admin-only, so never a self-service exploit,
990	  // but a support agent clicking "extend" was minting refundable balance.
991	  //
992	  // SEMANTICS CHOSEN: gifted months are recorded as sold at 100% off, and blended
993	  // into the rate the existing months are on. That is the honest reading of a gift
994	  // — those months cost the customer nothing, so nothing may prorate out of them —
995	  // and it is exact rather than blunt: the blend leaves the CASH VALUE of the
996	  // remaining window completely unchanged, so a customer who paid for 12 months and
997	  // was gifted a 13th still gets back precisely what those 12 paid months are worth
998	  // on a downgrade. Zeroing the whole term instead would confiscate what they paid;
999	  // leaving the rate alone is the money printer. Repeated gifts only ever dilute
1000	  // toward 100, so no number of calls can raise the payout.
1001	  //
1002	  // A NEGATIVE `days` removes months rather than adding them, so there is nothing
1003	  // to blend in: the customer keeps the rate they bought at over a shorter window,
1004	  // which strictly reduces any future credit. Blending negative months would push
1005	  // the rate the other way and over-credit what is left.
1006	  const gifted = days > 0;
1007	  const termPromoPercent = gifted
1008	    ? prorateBlendPercent({
1009	        currentPercent: resolveTermPromoPercent(server.termPromoPercent),
1010	        currentMonths: remainingMonths(server.expiresAt, Date.now()),
1011	        addedPercent: 100, // gifted: no cash changed hands for these months
1012	        addedMonths: (days * 86400_000) / MS_PER_AVG_MONTH,
1013	      })
1014	    : resolveTermPromoPercent(server.termPromoPercent);
1015	
1016	  await db.server.update({
1017	    where: { id: serverId },
1018	    data: { expiresAt: new Date(base + days * 86400_000), termPromoPercent },
1019	  });
1020	  await audit(
1021	    admin.id,
1022	    "admin.extend_server",
1023	    `${serverId} ${days}d${gifted ? ` gifted (rate basis ${server.termPromoPercent ?? "null"}% -> ${termPromoPercent}% off)` : ""}`,
1024	  );
1025	  revalidatePath("/admin/subscriptions");
1026	  return {};
1027	}
