45	/** Load the actor's membership in an org, or null if they aren't a member. */
46	async function actorMembership(orgId: string, userId: string) {
47	  if (!orgId) return null;
48	  return db.membership.findUnique({
49	    where: { orgId_userId: { orgId, userId } },
50	  });
51	}
