266	/**
267	 * Change a member's role. Only OWNER/ADMIN act. The owner's own membership is
268	 * pinned to OWNER and cannot be downgraded here.
269	 *
270	 * Takes a `membershipId`, not a `userId`: the client is never sent co-members'
271	 * user ids any more (see app/dashboard/team/page.tsx), so it has none to send
272	 * back. The org is derived from the membership rather than trusted from the
273	 * caller, which also removes the chance of a mismatched (orgId, userId) pair.
274	 */
275	export async function updateMemberRole(
276	  membershipId: string,
277	  role: string,
278	): Promise<{ error?: string; ok?: boolean }> {
279	  const user = await requireUser();
280	  const wantRole = String(role ?? "").toUpperCase();
281	  if (!isRole(wantRole) || wantRole === "OWNER") {
282	    return { error: "Pick a role of ADMIN, MEMBER or BILLING." };
283	  }
284	
285	  const target = await db.membership.findUnique({ where: { id: String(membershipId ?? "") } });
286	  if (!target) return { error: "That person isn't a member of this organization." };
287	
288	  const actor = await actorMembership(target.orgId, user.id);
289	  if (!actor || !canAdministerOrg(actor.role)) {
290	    return { error: "You don't have permission to change roles in this organization." };
291	  }
292	
293	  const org = await db.organization.findUnique({
294	    where: { id: target.orgId },
295	    select: { ownerId: true },
296	  });
297	  if (!org) return { error: "Organization not found." };
298	  if (target.userId === org.ownerId || target.role === "OWNER") {
299	    return { error: "The organization owner's role can't be changed." };
300	  }
301	
302	  await db.membership.update({
303	    where: { id: target.id },
304	    data: { role: wantRole },
305	  });
306	  await db.auditLog.create({
307	    data: {
308	      userId: user.id,
309	      action: "org.member_role_changed",
310	      detail: `${target.userId} → ${wantRole}`,
311	    },
312	  });
313	  revalidatePath("/dashboard/team");
314	  return { ok: true };
315	}
