341	  }
342	
343	  await db.membership.delete({ where: { id: target.id } });
344	  await db.auditLog.create({
345	    data: { userId: user.id, action: "org.member_removed", detail: target.userId },
346	  });
347	  revalidatePath("/dashboard/team");
348	  return { ok: true };
349	}
