351	/**
352	 * Leave an organization. The owner can't leave their own org (they'd have to
353	 * transfer ownership first — a follow-up), everyone else may.
354	 */
355	export async function leaveOrg(orgId: string): Promise<{ error?: string; ok?: boolean }> {
356	  const user = await requireUser();
357	
358	  const org = await db.organization.findUnique({ where: { id: orgId }, select: { ownerId: true } });
