import { NextRequest, NextResponse } from "next/server";
import { createReadStream } from "fs";
import { stat } from "fs/promises";
import path from "path";
import { Readable } from "stream";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";
import { checkRateLimit } from "@/lib/rate-limit";
import { listBackups, backupDumpDir } from "@/lib/proxmox";

/**
 * Secure customer backup download.
 *
 *   GET /api/servers/[serverId]/backups/download?volid=backup:backup/vzdump-...zst
 *     -> streams the vzdump archive as an attachment.
 *
 * SECURITY (the whole point of the card): a customer must only ever be able to
 * download a backup of a server THEY own. Two independent guards:
 *   1. Ownership — the server row must belong to the session user (or an admin).
 *   2. Tenancy of the archive — the requested volid must appear in this server's
 *      OWN backup listing (listBackups(vmid) is filtered by the server's vmid).
 *      This is the identical guard requestRestore() uses, so a guessed/forged
 *      volid for another tenant's vmid is rejected before any disk access.
 * Only after both pass do we touch the filesystem, and even then the resolved
 * path is confined to the backup dump dir (basename only, no traversal).
 *
 * Proxmox exposes no HTTP endpoint that streams a .vma.zst archive, so the file
 * is read off the host filesystem (the web app runs on the Proxmox host, same as
 * the platform-backups status reads).
 */
export const dynamic = "force-dynamic";

// Only ever serve real vzdump archives — never anything else in the dump dir.
const ARCHIVE_RE = /^vzdump-[A-Za-z0-9._-]+\.(vma|tar)(\.(zst|gz|lzo))?$/;

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id: serverId } = await params;

  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const rl = checkRateLimit(`backups:download:${user.id}`, { max: 20, windowMs: 60_000 });
  if (!rl.ok) {
    return NextResponse.json(
      { error: "too many downloads — slow down", retryAfterSec: rl.retryAfterSec },
      { status: 429, headers: { "Retry-After": String(rl.retryAfterSec) } }
    );
  }

  // 1. Ownership.
  const server = await db.server.findUnique({
    where: { id: serverId },
    select: { id: true, userId: true, vmid: true },
  });
  if (!server || (server.userId !== user.id && user.role !== "ADMIN")) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }
  if (!server.vmid) {
    return NextResponse.json({ error: "server has no VM yet" }, { status: 400 });
  }

  const volid = req.nextUrl.searchParams.get("volid");
  if (!volid) return NextResponse.json({ error: "missing volid" }, { status: 400 });

  // 2. Tenancy of the archive — must belong to THIS server's vmid.
  let owned: Array<{ volid: string }>;
  try {
    owned = (await listBackups(server.vmid)) as Array<{ volid: string }>;
  } catch {
    return NextResponse.json(
      { error: "could not verify the backup — the hypervisor is briefly unavailable" },
      { status: 502 }
    );
  }
  if (!owned.some((b) => b.volid === volid)) {
    return NextResponse.json({ error: "that backup was not found for this server" }, { status: 404 });
  }

  // Resolve volid -> on-disk file. The basename is the only part we trust; it
  // must be a real vzdump archive name and cannot escape the dump dir.
  const filename = volid.split("/").pop() ?? "";
  if (!ARCHIVE_RE.test(filename)) {
    return NextResponse.json({ error: "unsupported backup format" }, { status: 400 });
  }
  const dumpDir = await backupDumpDir();
  const filePath = path.join(dumpDir, filename);
  if (path.dirname(path.resolve(filePath)) !== path.resolve(dumpDir)) {
    // Defence in depth — basename regex already forbids separators.
    return NextResponse.json({ error: "invalid backup path" }, { status: 400 });
  }

  let size: number;
  try {
    const st = await stat(filePath);
    if (!st.isFile()) throw new Error("not a file");
    size = st.size;
  } catch {
    return NextResponse.json(
      { error: "backup archive is not available on the host for download" },
      { status: 502 }
    );
  }

  // Stream the file rather than buffering — archives are multi-GB.
  const nodeStream = createReadStream(filePath);
  const webStream = Readable.toWeb(nodeStream) as unknown as ReadableStream<Uint8Array>;

  return new NextResponse(webStream, {
    status: 200,
    headers: {
      "Content-Type": "application/octet-stream",
      "Content-Length": String(size),
      "Content-Disposition": `attachment; filename="${filename.replace(/["\\]/g, "_")}"`,
      "Cache-Control": "private, no-store",
    },
  });
}
