import { NextRequest, NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { db } from "@/lib/db";
import { invoiceBranding, renderInvoiceHTML } from "@/lib/invoices";

/**
 * Returns the branded, print-ready invoice as standalone HTML.
 *
 * NOTE: There is no PDF library installed and we cannot add dependencies, so
 * this is the pragmatic approach — the page ships with a print-optimised
 * stylesheet and a "Print / Save as PDF" button; the browser's Print → Save
 * as PDF produces the downloadable document.
 */
export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
  const { id } = await params;
  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const invoice = await db.invoice.findUnique({
    where: { id },
    include: { user: { select: { name: true, email: true } } },
  });
  if (!invoice) return NextResponse.json({ error: "not found" }, { status: 404 });

  const isOwner = invoice.userId === user.id;
  const isAdmin = user.role === "ADMIN";
  if (!isOwner && !isAdmin) {
    return NextResponse.json({ error: "forbidden" }, { status: 403 });
  }

  // The downloaded document must carry the same identifier the dashboard showed the
  // customer — an accountant reconciling "INV-00012" against a file headed "#00012" has
  // to guess whether they are the same invoice. This is also the one render site where
  // `company_legal_name` / `company_address` become visible.
  const html = renderInvoiceHTML(invoice, invoice.user, await invoiceBranding());
  return new NextResponse(html, {
    status: 200,
    headers: {
      "Content-Type": "text/html; charset=utf-8",
      "Cache-Control": "private, no-store",
    },
  });
}
