import { NextRequest, NextResponse } from "next/server";
import { db } from "@/lib/db";
import { currentUser } from "@/lib/auth";

export const dynamic = "force-dynamic";

/**
 * GET /api/claude/[id]
 * Ownership-checked live status for a ClaudeBuild — polled by the client viewer.
 * Returns { status, steps, log, plan }. `plan` is the JSON string of proposed
 * commands (present once the build reaches AWAITING_APPROVAL), or null.
 */
export async function GET(
  _req: NextRequest,
  { params }: { params: Promise<{ id: string }> }
) {
  const { id } = await params;

  const user = await currentUser();
  if (!user) return NextResponse.json({ error: "unauthorized" }, { status: 401 });

  const build = await db.claudeBuild.findUnique({
    where: { id },
    select: { userId: true, status: true, steps: true, log: true, plan: true },
  });
  if (!build || (build.userId !== user.id && user.role !== "ADMIN")) {
    return NextResponse.json({ error: "not found" }, { status: 404 });
  }

  return NextResponse.json(
    { status: build.status, steps: build.steps, log: build.log, plan: build.plan },
    { headers: { "cache-control": "no-store" } }
  );
