151	/**
152	 * Fetch the signed-in user's profile from the OIDC userinfo endpoint with the
153	 * bearer access token. Returns the normalised profile or a safe error string.
154	 * `emailVerified` normalises Google's boolean-or-"true"-string form.
155	 */
156	export async function googleFetchProfile(
157	  accessToken: string,
158	): Promise<{ profile?: GoogleProfile; error?: string }> {
159	  let res: Response;
160	  try {
161	    res = await fetch(GOOGLE_USERINFO_URL, {
162	      headers: { Authorization: `Bearer ${accessToken}`, Accept: "application/json" },
163	      cache: "no-store",
164	    });
165	  } catch {
166	    return { error: "Couldn't reach Google to read your profile. Try again shortly." };
167	  }
168	
169	  let parsed: UserinfoResponse | null = null;
170	  try {
171	    parsed = (await res.json()) as UserinfoResponse;
172	  } catch {
173	    parsed = null;
174	  }
175	
176	  if (!res.ok || !parsed?.sub || !parsed?.email) {
177	    return { error: "Google didn't return your profile. Please try again." };
178	  }
179	
180	  const emailVerified = parsed.email_verified === true || parsed.email_verified === "true";
181	  return {
182	    profile: {
183	      sub: parsed.sub,
184	      email: parsed.email,
185	      emailVerified,
186	      name: (parsed.name ?? parsed.given_name ?? parsed.email.split("@")[0] ?? "").trim(),
187	      picture: parsed.picture ?? null,
188	    },
189	  };
190	}
