593	export async function removeAlias(id: number, mailboxAddress?: string): Promise<Result> {
594	  const { user, address } = await resolveMailbox(mailboxAddress);
595	  const limited = gate(`mail:alias:${user.id}`, 20, 60_000);
596	  if (limited) return limited;
597	  if (!mailcowConfigured()) return { ok: false, error: "Mail server is not configured yet." };
598	  if (!Number.isFinite(id)) return { ok: false, error: "Invalid alias." };
599	
600	  const domain = domainOf(address);
601	  const owned = await ownedDomains(user.id);
602	  if (!owned.has(domain)) return { ok: false, error: "You don't own this mailbox's domain." };
603	
604	  try {
605	    // Confirm the alias belongs to this owned domain before deleting.
606	    const list = await mcListAliases(domain);
607	    const match = list.find((a) => a.id === id);
608	    if (!match) return { ok: false, error: "That alias no longer exists on your domain." };
609	    await mcDeleteAlias(id);
610	    return { ok: true };
611	  } catch (e) {
612	    return { ok: false, error: friendly(e) };
613	  }
614	}
