import { NextResponse } from "next/server";
import { currentUser } from "@/lib/auth";
import { jsonError } from "@/lib/tools/api";
import { checkRateLimit } from "@/lib/rate-limit";
import {
  generateSuggestions,
  readIdea,
  readKeywords,
  readTlds,
  readTone,
  MIN_IDEA_LEN,
} from "@/lib/tools/domain-suggest";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

/**
 * Domain-name generator for the signed-in customer portal.
 *
 * Same brief → names → live availability pipeline as the public marketing tool
 * (both call `generateSuggestions`), but this surface is authenticated, so:
 *
 *   - The caller must be signed in.
 *   - Throttling keys on the ACCOUNT (`user.id`), a real identity, not the
 *     shared, spoofable client IP. A logged-in customer gets a more generous
 *     budget than an anonymous visitor while the platform Claude key and the
 *     metered registrar stay protected. (The IP-keyed limiter would lump a whole
 *     office behind one NAT into a single bucket; the account key is the honest
 *     one here.)
 *
 * Every "Register" the UI renders points at /dashboard/domains/register?domain=…,
 * the existing purchase path, which re-checks availability and price before charge.
 */

export async function POST(req: Request) {
  const user = await currentUser();
  if (!user) {
    return NextResponse.json({ ok: false, error: "Sign in to generate domain ideas." }, { status: 401 });
  }

  // Burst then hourly, both keyed on the account. AI + registrar cost money even
  // for a paying customer, so the windows are generous but not unbounded.
  const burst = checkRateLimit(`tool:domain-generator:user:${user.id}`, { max: 12, windowMs: 60_000 });
  if (!burst.ok) {
    return NextResponse.json(
      { ok: false, error: `You're generating quickly — try again in ${burst.retryAfterSec}s.` },
      { status: 429, headers: { "Retry-After": String(burst.retryAfterSec) } },
    );
  }
  const hourly = checkRateLimit(`tool:domain-generator-hourly:user:${user.id}`, { max: 120, windowMs: 60 * 60_000 });

