10	 * exactly once per request. The outcome is then shown by /verify-email, which
11	 * renders and mutates nothing.
12	 *
13	 * `GET` is correct here despite being a mutation: the customer arrives by
14	 * clicking a link in mail, and the "unsafe method" objection does not apply
15	 * because the token IS the intent and it is single-use. Mail security scanners
16	 * that pre-fetch links will consume the token — which is why
17	 * `consumeVerificationToken` reports an already-verified account as a success
18	 * rather than an error. A scanner that can read the link is inside the
19	 * recipient's own mail infrastructure, so it fetching the link is evidence of
20	 * exactly the control we are testing for, not a bypass of it.
21	 */
22	export async function GET(req: NextRequest) {
