27	  } catch (e) {
28	    console.error("[verify-email] failed to consume token:", e);
29	    status = "error";
30	  }
31	  const dest = new URL("/verify-email", req.nextUrl.origin);
32	  dest.searchParams.set("status", status);
33	  return NextResponse.redirect(dest, { status: 303 });
34	}
